python3 - <<'EOF'
import re
pl=open("docs/packages/rllab/pipelines.md").read()
c=open("docs/packages/rllab/contract.md").read()
syms=set(re.findall(r"^### ([a-z]+\.\w+):",c,re.M))
use={}
cur=None
for line in pl.splitlines():
    m=re.match(r"## (PL-\d+):",line)
    if m: cur=m.group(1); continue
    m=re.match(r"\| \d+ \| `(\w+)` \| ([a-z_]+)",line)
    if m and cur:
        s=f"{m.group(2)}.{m.group(1)}"
        if s in syms: use.setdefault(s,set()).add(cur)
out=[];sec=None;changes=[]
for line in c.splitlines():
    m=re.match(r"^### ([a-z]+\.\w+):",line)
    if m: sec=m.group(1)
    if line.startswith("- **Used by:**") and sec:
        base=re.sub(r";\s*PL-\d+(, PL-\d+)*\s*$","",line)
        want=sorted(use.get(sec,()))
        new=base+("; "+", ".join(want) if want else "")
        if new!=line: changes.append((sec,line.split("**Used by:**")[1],new.split("**Used by:**")[1]))
        line=new
    out.append(line)
open("docs/packages/rllab/contract.md","w").write("\n".join(out)+"\n")
for ch in changes: print(ch[0],":",ch[1].strip(),"->",ch[2].strip())
EOF
